const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const outDir = path.join(root, "source", "data-model", "lessons");
const imageBase = "images/vocab";

function vid(lesson, n) { return `v_l${lesson}_${String(n).padStart(2, "0")}`; }
function vocab(lesson, rows) {
  return rows.map((x, i) => ({
    id: vid(lesson, i + 1), hanzi: x[0], word: x[0], pinyin: x[1], pos: x[2],
    english: x[3], sourceType: "textbook", tags: [`L${lesson}`], category: x[4] || "general",
    image: `${imageBase}/hsk1-l${lesson}/${String(i + 1).padStart(2, "0")}_${x[5]}.png`
  }));
}
function line(x, i) { return { order: i + 1, speaker: x[0], hanzi: x[1], pinyin: x[2], english: x[3], sourceType: "textbook" }; }
function text(id, title, setting, lines) { return { id, title, setting, sourceType: "textbook", lines: lines.map(line) }; }
function sh(a) { return a.slice().sort((x, y) => String(x).localeCompare(String(y), "zh-CN")); }
function pyMap(voc, extra = {}) {
  const common = {
    "我": "wǒ", "我们": "wǒmen", "你": "nǐ", "你们": "nǐmen", "您": "nín", "他": "tā", "他们": "tāmen", "她": "tā",
    "王老师": "Wáng lǎoshī", "老师": "lǎoshī", "王老师的姐姐": "Wáng lǎoshī de jiějie", "姐姐": "jiějie", "李文": "Lǐ Wén", "安妮": "Ānnī", "白家月": "Bái Jiāyuè",
    "一": "yī", "一杯": "yì bēi", "一斤": "yì jīn", "一个": "yí gè", "一半": "yíbàn", "半斤": "bàn jīn", "几个": "jǐ gè", "九个": "jiǔ gè", "40个": "sìshí gè", "20个": "èrshí gè", "八点": "bā diǎn",
    "个": "gè", "杯": "bēi", "斤": "jīn", "件": "jiàn", "年": "nián", "小时": "xiǎoshí",
    "吗": "ma", "呢": "ne", "吧": "ba", "的": "de", "了": "le", "和": "hé", "也": "yě", "还": "hái", "再": "zài", "都": "dōu", "很": "hěn", "非常": "fēicháng", "太": "tài", "多": "duō", "没": "méi", "不": "bù", "不要": "búyào", "不是": "bú shì", "不早": "bù zǎo",
    "是": "shì", "有": "yǒu", "有些": "yǒuxiē", "有的": "yǒude", "可以": "kěyǐ", "想": "xiǎng", "喜欢": "xǐhuan", "爱吃": "ài chī", "好吃": "hǎochī", "好看": "hǎokàn", "全部": "quánbù", "忙": "máng",
    "看": "kàn", "看书": "kàn shū", "看电影": "kàn diànyǐng", "看见": "kànjiàn", "写": "xiě", "听": "tīng", "听见": "tīngjiàn", "说话": "shuōhuà", "睡觉": "shuìjiào", "上学": "shàngxué", "开始": "kāishǐ", "动作完成": "dòngzuò wánchéng", "离合词": "líhécí",
    "问": "wèn", "问一下": "wèn yíxià", "问一个问题": "wèn yí gè wèntí", "打电话": "dǎ diànhuà", "给我": "gěi wǒ", "请坐": "qǐng zuò", "请": "qǐng", "坐": "zuò", "喝": "hē", "吃": "chī", "要": "yào", "接你们": "jiē nǐmen", "接": "jiē", "住": "zhù", "见": "jiàn",
    "什么": "shénme", "谁": "shéi", "哪儿": "nǎr", "哪里": "nǎli", "哪个": "nǎge", "哪些": "nǎxiē", "怎么样": "zěnmeyàng", "怎么": "zěnme", "几点": "jǐ diǎn",
    "这个": "zhège", "那个": "nàge", "这些": "zhèxiē", "那": "nà", "这": "zhè", "这里": "zhèlǐ", "在": "zài", "在这边": "zài zhèbiān",
    "去": "qù", "去了": "qùle", "去机场": "qù jīchǎng", "到": "dào", "到北京": "dào Běijīng", "到大兴机场": "dào Dàxīng Jīchǎng", "上": "shàng", "后": "hòu", "前": "qián", "今年": "jīnnián", "去年": "qùnián", "明年": "míngnián", "前几年": "qián jǐ nián", "星期天": "Xīngqītiān", "星期日": "Xīngqīrì", "早上": "zǎoshang", "中午": "zhōngwǔ",
    "手机": "shǒujī", "小店": "xiǎo diàn", "饭店": "fàndiàn", "餐馆": "cānguǎn", "牛奶": "niúnǎi", "饺子": "jiǎozi", "中国菜": "Zhōngguó cài", "菜": "cài", "电影": "diànyǐng", "书": "shū", "车": "chē", "人": "rén", "做": "zuò", "家": "jiā",
    "汉语": "Hànyǔ", "汉字": "Hànzì", "字": "zì", "中学": "zhōngxué", "小学": "xiǎoxué", "中学生": "zhōngxuésheng", "小学生": "xiǎoxuéshēng",
    "北京": "Běijīng", "西安": "Xī'ān", "大兴机场": "Dàxīng Jīchǎng", "机场": "jīchǎng", "飞机": "fēijī", "火车": "huǒchē", "家人": "jiārén", "时间": "shíjiān", "男朋友": "nánpéngyou",
    "好的": "hǎo de", "对": "duì", "谢谢": "xièxie", "大家": "dàjiā", "儿子": "érzi", "女儿": "nǚ'ér"
  };
  return Object.assign(common, Object.fromEntries(voc.map((v) => [v.word, v.pinyin])), extra);
}
function phrasePinyin(s, map) {
  let out = String(s || "");
  Object.keys(map).sort((a, b) => b.length - a.length).forEach((k) => { out = out.split(k).join(` ${map[k]} `); });
  return out.replace(/[，。？！,.?!：:；;]/g, " ").replace(/\s+/g, " ").trim();
}
function pinyinFor(opts, py) { return opts.map((x) => py[x] || phrasePinyin(x, py)); }
function qBase(id, type, prompt, data, answer, kp, sourceType = "teaching_extension") {
  return { id, type, stage: "in_class", prompt_cn: prompt, prompt_en: "Choose the best answer.", data, correct_answer: answer, kp, sourceType };
}
function imageGuess(lesson, voc) {
  return voc.slice(0, 10).map((v, i) => {
    const opts = sh([v.word].concat(voc.filter((x) => x.word !== v.word).slice(i + 1, i + 4).map((x) => x.word)));
    while (opts.length < 4) opts.push(voc[(i + opts.length + 3) % voc.length].word);
    return qBase(`v1_l${lesson}_${i + 1}`, "image_guess", "图片猜词。", { image: v.image, image_hint: v.word, options: opts.slice(0, 4), correct_index: opts.slice(0, 4).indexOf(v.word) }, v.word, v.word, "textbook");
  });
}
function vocabFill(lesson, rows, py) {
  return rows.map((x, i) => qBase(`v5_l${lesson}_${i + 1}`, "vocab_fill", "选词填空。", {
    sentence: x[0], sentence_pinyin: x[1], options: x[2], options_pinyin: pinyinFor(x[2], py), correct_index: x[2].indexOf(x[3])
  }, x[3], x[4] || x[3], i < 6 ? "textbook" : "teaching_extension"));
}
function wordMatch(lesson, rows, prefix, prompt, py, type = "word_match") {
  return rows.map((pairs, i) => ({
    id: `${prefix}_l${lesson}_${i + 1}`, type, stage: "in_class", prompt_cn: prompt, prompt_en: "Match each item with the best answer.",
    data: { pairs: pairs.map(([left, right]) => ({ left, left_pinyin: phrasePinyin(left, py), right, right_pinyin: /[\u4e00-\u9fff]/.test(right) ? phrasePinyin(right, py) : "" })), order: [2, 0, 3, 1] },
    correct_answer: "全部配对正确", sourceType: "teaching_extension"
  }));
}
function transform(lesson, rows) {
  return rows.map((x, i) => qBase(`v4_l${lesson}_${i + 1}`, "sentence_transform", "选择正确的问句。", {
    source_sentence: x[0], source_pinyin: x[1], options: x[2], options_pinyin: x[3], correct_index: x[2].indexOf(x[4])
  }, x[4], "句型转换：给答句选问句"));
}
function ordering(lesson, rows) {
  return rows.map((x, i) => ({ id: `g1_l${lesson}_${i + 1}`, type: "ordering", stage: "in_class", prompt_cn: "连词成句。", prompt_en: "Put the chunks in order.", data: { chunks: x[1], chunks_pinyin: x[2] }, correct_answer: x[0], acceptable_answers: [x[0], `${x[0]}。`, `${x[0]}？`], sourceType: "teaching_extension" }));
}
function translation(lesson, rows) {
  return rows.map((x, i) => qBase(`trc_l${lesson}_${i + 1}`, "translation_choice", "根据英文和俄文选择中文句子。", { question_en: x[0], question_ru: x[1], options: x[3], correct_index: x[3].indexOf(x[2]) }, x[2], "译文选句", x[4] || "textbook"));
}
function textQa(lesson, groups) {
  return groups.map((g, i) => ({ id: `ttq_l${lesson}_${i + 1}`, type: "text_qa_group", stage: "in_class", prompt_cn: "课文问答：根据课文内容回答。", prompt_en: "Text Q&A: answer from the dialogue.", data: { title: g.title, passage: g.passage, passage_pinyin: g.passagePinyin, questions: g.questions.map((q) => ({ question_cn: q[0], question_pinyin: q[1], answer: q[2], answer_pinyin: q[3], options: q[4], correct_index: q[4].indexOf(q[2]) })) }, correct_answer: "见每题答案", sourceType: "textbook" }));
}
function pictureTalk(lesson, rows, vocByWord) {
  return rows.map((x, i) => ({ id: `r4_l${lesson}_pt_${String(i + 1).padStart(2, "0")}`, type: "oral", stage: "in_class", prompt_cn: x[0], prompt_en: "Look at the picture and answer in Chinese.", data: { question: x[0], question_pinyin: x[1], instructions: "请用中文回答这个问题。", context: "教学扩展", image: vocByWord[x[2]].image, sampleAnswer: x[3], sampleAnswerPinyin: x[4], patternType: x[5] }, openEnded: true, needsTeacherReview: true, cloudWall: true, weakPoints: `输出：${x[5]}`, sourceType: "teaching_extension" }));
}
function hanzi(chars) { return Array.from(new Set(chars.split(""))).filter((c) => /[\u4e00-\u9fff]/.test(c)).map((char) => ({ char, sourceType: "textbook" })); }
function hanziRecognition(groups) { return { enabled: true, showPinyin: false, rounds: [{ id: "hanzi_to_pinyin", title: "看汉字选拼音", titleEn: "Choose pinyin" }, { id: "hanzi_to_meaning", title: "看汉字选意思", titleEn: "Choose meaning" }, { id: "meaning_to_hanzi", title: "看意思选汉字", titleEn: "Choose character" }], groups }; }
function grammar(lesson, rows) { return rows.map((g, i) => ({ id: `g_l${lesson}_${String(i + 1).padStart(2, "0")}`, title: g.title, titleEn: g.titleEn, structure: g.structure, explanation: g.explanation, examples: g.examples.map((e) => ({ hanzi: e[0], pinyin: e[1], english: e[2], sourceType: e[3] || "textbook" })) })); }
function extRows(v, rows) {
  const r = rows[v.word] || [[v.word, v.pinyin, v.english], [`这个${v.word}`, `zhège ${v.pinyin}`, `this ${v.english}`], [`我会说“${v.word}”。`, `Wǒ huì shuō ${v.pinyin}.`, `I can say ${v.word}.`]];
  return r.slice(0, 3).map((e) => ({ hanzi: e[0], pinyin: e[1], english: e[2], sourceType: "teaching_extension" }));
}
function lessonData(c) {
  const voc = vocab(c.lesson, c.vocabRows), byWord = Object.fromEntries(voc.map((v) => [v.word, v])), py = pyMap(voc, c.py || {}), gr = grammar(c.lesson, c.grammarRows);
  const groups = {
    v1_image_guess: imageGuess(c.lesson, voc), v5_vocab_fill: vocabFill(c.lesson, c.fill, py),
    v7_word_match: wordMatch(c.lesson, c.wordMatch, "v7", "词句匹配。", py),
    v8_memory_match: wordMatch(c.lesson, c.memoryMatch, "v8", "词了个词。", py, "memory_match"),
    v4_complete_sentence: transform(c.lesson, c.transform), g1_ordering: ordering(c.lesson, c.ordering),
    r3_translation_choice: translation(c.lesson, c.translation), r2_passage_choice: textQa(c.lesson, c.textQa),
    r4_picture_talk: pictureTalk(c.lesson, c.pictureTalk, byWord)
  };
  return {
    schemaVersion: "1.0.0",
    meta: { level: "HSK1", lessonId: `L${c.lesson}`, lessonKey: `HSK1-L${c.lesson}`, title: c.title, titleEn: c.titleEn, topic: c.topic, sourceTextPolicy: "保留教材原句；新增内容标记为教学扩展", dataQualityNotes: [`根据 textbook data/L${c.lesson}.txt 生成；L${c.lesson} 课文原句完整保留。`, `已按 L11-L12 当前结构制作：课前10题、课中题型题量、汉字练习与英俄译文选句字段对齐。`] },
    features: { pinyin: true, hanziWritingDemo: true, vocabExamples: true, competition: true, postClassHomework: true },
    vocabulary: voc, grammar: gr, texts: c.texts,
    vocabExtensions: Object.fromEntries(voc.map((v) => [v.id, { word: v.word, examples: extRows(v, c.examples || {}), collocations: extRows(v, c.examples || {}) }])),
    grammarTeachingNotes: Object.fromEntries(gr.map((g, i) => [g.id, { title: g.title, titleEn: g.titleEn, structure: g.structure, structureEn: c.grammarRows[i].structureEn, structureRu: c.grammarRows[i].structureRu, english: c.grammarRows[i].english, russian: c.grammarRows[i].russian, formula: { pattern: g.structure, patternEn: c.grammarRows[i].structureEn, patternRu: c.grammarRows[i].structureRu }, examples: g.examples }])),
    preClass: { warmup: c.warmup, questions: c.preQuestions },
    inClass: { questionGroups: groups }, classProQuestions: { pictureGuess: groups.v1_image_guess, vocabFill: groups.v5_vocab_fill, wordMatch: groups.v7_word_match, matchingGame: groups.v8_memory_match, sentenceTransform: groups.v4_complete_sentence, ordering: groups.g1_ordering, translationChoice: groups.r3_translation_choice, textQa: groups.r2_passage_choice, pictureTalk: groups.r4_picture_talk },
    hanziWriting: { characters: hanzi(c.hanziChars) }, hanziRecognition: hanziRecognition(c.hanziGroups),
    postClassHomework: c.postClassHomework, report: { focus: c.reportFocus }
  };
}

