  text("t_l15_01", "课文一：爱吃哪个菜", "在李文家，朋友们品尝中餐。", [["李文", "你们爱吃哪个菜？", "Nǐmen ài chī nǎge cài?", "Which dish do you like?"], ["白家月", "我喜欢这个，也喜欢那个。", "Wǒ xǐhuan zhège, yě xǐhuan nàge.", "I like this one, and I also like that one."], ["陈天中", "这些菜都好吃，还很好看。", "Zhèxiē cài dōu hǎochī, hái hěn hǎokàn.", "All these dishes are delicious and look great."], ["李文", "我爱吃中国菜，也喜欢做。大家多吃点儿。", "Wǒ ài chī Zhōngguó cài, yě xǐhuan zuò. Dàjiā duō chī diǎnr.", "I like eating Chinese food and also like cooking it. Please eat more."]]),
  text("t_l15_02", "课文二：想去北京", "大家边吃饭边谈论度假计划。", [["李文", "你们都想去哪儿？", "Nǐmen dōu xiǎng qù nǎr?", "Where do you all want to go?"], ["安妮", "去年我和男朋友去了西安，今年我想去北京。", "Qùnián wǒ hé nánpéngyou qùle Xī'ān, jīnnián wǒ xiǎng qù Běijīng.", "Last year my boyfriend and I went to Xi'an. This year I want to go to Beijing."], ["白家月", "前几年去了西安，非常好玩儿。今年我也想去北京。", "Qián jǐ nián wǒ qùle Xī'ān, fēicháng hǎowánr. Jīnnián wǒ yě xiǎng qù Běijīng.", "I went to Xi'an a few years ago. It was fun. This year I also want to go to Beijing."], ["李文", "我和王老师都是北京人，北京非常漂亮。", "Wǒ hé Wáng lǎoshī dōu shì Běijīng rén, Běijīng fēicháng piàoliang.", "Ms. Wang and I are both from Beijing. Beijing is very beautiful."]]),
  text("t_l15_03", "课文三：大兴机场见", "白家月、安妮和王老师谈论去北京旅游。", [["王一飞", "你们的飞机到北京要几个小时？", "Nǐmen de fēijī dào Běijīng yào jǐ gè xiǎoshí?", "How many hours will your flight take to Beijing?"], ["白家月", "九个小时。", "Jiǔ gè xiǎoshí.", "Nine hours."], ["王一飞", "我家人都在北京，星期天我姐姐也有时间，她可以去机场接你们，你们也可以住我家。", "Wǒ jiārén dōu zài Běijīng, Xīngqītiān wǒ jiějie yě yǒu shíjiān, tā kěyǐ qù jīchǎng jiē nǐmen, nǐmen yě kěyǐ zhù wǒ jiā.", "My family is in Beijing. My sister can pick you up at the airport, and you can stay at my home."], ["安妮", "我们星期日早上八点到大兴机场，早不早？", "Wǒmen Xīngqīrì zǎoshang bā diǎn dào Dàxīng Jīchǎng, zǎo bu zǎo?", "We arrive at Daxing Airport at 8 a.m. on Sunday. Is that early?"], ["王一飞", "不早。", "Bù zǎo.", "Not early."], ["白家月", "谢谢老师！那我和您姐姐在大兴机场见！", "Xièxie lǎoshī! Nà wǒ hé nín jiějie zài Dàxīng Jīchǎng jiàn!", "Thank you! Then I will meet your sister at Daxing Airport."]])
